(()=>{const products=[];for(const [vehicle,prefix,route] of [['Porsche 911','porsche','porsche-911.html#configurator'],['Golf R Mk7','golf','golf-r.html#finishes']]){for(const [slug,name,category,desc,img,style] of [['wheels','Custom wheel set','Wheels','Choose your spoke design and discuss sizing for your vehicle.',prefix==='golf'?'golf-rear-split.png':'porsche-sport.png',''],['lip','Carbon front lip','Aero','A sharper front-end finish, quoted with installation.',prefix+'-front-lip.png',''],['diffuser','Carbon rear diffuser','Aero','Define the rear profile with a carbon-finish aero option.',prefix+'-rear-aero.png',''],['steering','Custom steering wheel','Steering wheels','Leather, carbon or Alcantara. Choose your finish in the build studio.',prefix+'-steering.png','steering'],['tips','Oval exhaust tips','Exhaust tips','A finishing detail for your rear build. Fitment checked before ordering.',prefix+'-rear-aero.png','']])products.push({id:prefix+'-'+slug,name,vehicle,category,desc,img,style,route})}
const target=document.querySelector('#products'),vehicle=document.querySelector('#shop-vehicle'),category=document.querySelector('#shop-category'),search=document.querySelector('#shop-search');
function render(){const q=search.value.trim().toLowerCase();const list=products.filter(p=>(vehicle.value==='all'||p.vehicle===vehicle.value)&&(category.value==='all'||p.category===category.value)&&(!q||(p.name+' '+p.desc+' '+p.vehicle).toLowerCase().includes(q)));target.replaceChildren();for(const p of list){const card=document.createElement('article');card.className='product';card.innerHTML=`<div class="product-visual ${p.style||('detail-'+p.id.split('-').pop())}" style="background-image:url('${p.img}')" role="img" aria-label="${p.name} design option"></div><span class="tag">${p.vehicle}</span><h3>${p.name}</h3><p>${p.desc}</p><p class="price">Request a quote</p><button class="outline-cta">${window.hocQuote.has(p.id)?'Added to quote ✓':'Add to quote +'}</button><a class="text-link" href="${p.route}">Preview your build ↗</a>`;card.querySelector('button').onclick=()=>{window.hocQuote.add({id:p.id,name:p.name,vehicle:p.vehicle});card.querySelector('button').textContent='Added to quote ✓'};target.append(card)}document.querySelector('#result-count').textContent=list.length+' design options';document.querySelector('#no-results').hidden=!!list.length}
[vehicle,category].forEach(x=>x.onchange=render);search.oninput=render;document.querySelector('#view-quote').onclick=()=>window.hocQuote.open();window.addEventListener('hoc-cart-change',render);render();})();
